export function courtBaseUrl(subdomain: string, preferHttp = false): string {
  return `${preferHttp ? "http" : "https"}://${subdomain}.sudrf.ru`;
}

/** Courts in a federal subject code (e.g. "13" = Мордовия). */
export function courtsByRegion(region: string): CourtEntry[] {
  return COURT_REGISTRY.filter((c) => c.region === region);
}
